                            "description": "Unique identifier for log event",
                            "default": "",
                            "examples": ["eventId1"],
                        },
                        "message": {
                            "$id": "#/items/anyOf/0/properties/message",
                            "type": "object",
                            "title": "The message schema",
                            "description": "Log data captured in CloudWatch Logs",
