def doc_with_field_type(field_type):
    class DocCreator(object):
        def create(self):
            doc = Document()
            if field_type == 'text':
                doc.text = 'aaa'
            elif field_type == 'buffer':
                doc.buffer = b'\x01\x02\x03'
            elif field_type == 'blob':
                doc.blob = np.array([1, 1, 1])
            return doc

    return DocCreator()

