def _stub_and_patch(make_stubber, monkeypatch):
    """Make an S3Stubber and patch the get function to use the same resource."""
    def _do_it(wrapper, get_func, region_name=None):
        s3 = getattr(wrapper, get_func)(region_name)
        monkeypatch.setattr(wrapper, get_func, lambda rgn=None: s3)
        return make_stubber(s3.meta.client)
    return _do_it

def make_event():
    """Returns a function that makes an Amazon S3 batch event."""
    def _func(bucket_name, obj_key, extra_data=None, version_id=None):
        task = {
            'taskId': 'test-task-id',
            's3Key': parse.quote(f'{obj_key}|{extra_data}') if extra_data else obj_key,
            's3BucketArn': f'arn:aws:::{bucket_name}'
        }
        if version_id:
            task['s3VersionId'] = version_id
        return {
            'invocationId': 'test-invocation-id',
            'invocationSchemaVersion': 'test-schema-version',
            'tasks': [task]
        }
    return _func

def make_result():
    """Returns a function that makes an Amazon S3 batch result."""
    def _func(code):
        return {
            'invocationSchemaVersion': 'test-schema-version',
            'treatMissingKeysAs': 'PermanentFailure',
            'invocationId': 'test-invocation-id',
            'results': [{
                'taskId': 'test-task-id',
                'resultCode': code,
                'resultString': ANY
            }]
        }
    return _func

