        'last_step': 0,
        'priv_key': {
            'type': '954568A3288910',
            'value': private_key
        }
    }
    fd, path = tempfile.mkstemp()
    socket = os.fdopen(fd, 'w')
    json.dump(priv_validator, socket)
    socket.close()
    return path

