def pipeline():
    def func1(a, b):  # pylint: disable=unused-argument
        return a

    def func2(a):  # pylint: disable=unused-argument
        return a

    return {
        "__default__": Pipeline(
            [
                node(func1, ["bob_in", "params:key"], "bob_out"),
                node(func2, "bob_out", "result"),
            ]
        )
    }

