        "params:key": MemoryDataSet("value"),
        "result": PickleDataSet("final.csv"),
    }
    layers = {"raw": {"bob_in"}, "final": {"result"}}

    catalog = DataCatalog(data_sets=data_sets)
    setattr(catalog, "layers", layers)

    return catalog

