def ganache_provider():
    """Get a ganache web3 provider."""
    return Web3.HTTPProvider(endpoint_uri="http://127.0.0.1:8545")

def web3_instance(ganache_provider):  # pylint: disable=redefined-outer-name
    """Get a web3 instance."""
    return Web3(ganache_provider)

def erc20_proxy_address():
    """Get the 0x ERC20 Proxy address."""
    return chain_to_addresses(ChainId.GANACHE).erc20_proxy

def weth_asset_data():  # pylint: disable=redefined-outer-name
    """Get 0x asset data for Wrapped Ether (WETH) token."""
    return asset_data_utils.encode_erc20(
        chain_to_addresses(ChainId.GANACHE).ether_token
    )

def weth_instance(web3_eth):  # pylint: disable=redefined-outer-name
    """Get an instance of the WrapperEther contract."""
    return web3_eth.contract(
        address=to_checksum_address(
            chain_to_addresses(ChainId.GANACHE).ether_token
        ),
        abi=abi_by_name("WETH9"),
    )

def zrx_address():
    """Get address of ZRX token for Ganache chain."""
    return chain_to_addresses(ChainId.GANACHE).zrx_token

def zrx_asset_data(zrx_address):  # pylint: disable=redefined-outer-name
    """Get 0x asset data for ZRX token."""
    return asset_data_utils.encode_erc20(zrx_address)

def contract_wrapper(ganache_provider):
    """Get a ContractMethod instance for testing."""
    return ContractMethod(
        web3_or_provider=ganache_provider,
        contract_address=chain_to_addresses(ChainId.GANACHE).ether_token,
    )

def erc20_wrapper(ganache_provider):
    """Get an instance of ERC20Token wrapper class for testing."""
    return ERC20Token(
        ganache_provider, chain_to_addresses(ChainId.GANACHE).ether_token
    )

def exchange_wrapper(ganache_provider):
    """Get an Exchange wrapper instance."""
    return Exchange(
        web3_or_provider=ganache_provider,
        contract_address=chain_to_addresses(ChainId.GANACHE).exchange,
    )

def setUp(self):
    super(TestACLRenames, self).setUp()

    self.load_sample(testsamples.sample_students)

    # Add column to Schools to use with User Attribute.
    self.engine.apply_user_actions([useractions.from_repr(ua) for ua in (
      ['AddColumn', 'Schools', 'LiasonEmail', {'type': 'Text'}],
      ['AddRecord', '_grist_ACLResources', -1, {'tableId': '*', 'colIds': '*'}],
      ['AddRecord', '_grist_ACLRules', None, {
        'resource': -1,
        'userAttributes': json.dumps(user_attr1),
      }],
      ['AddRecord', '_grist_ACLResources', -2, {
        'tableId': 'Students', 'colIds': 'firstName,lastName'
      }],
      ['AddRecord', '_grist_ACLResources', -3, {
        'tableId': 'Students', 'colIds': '*'
      }],
      ['AddRecord', '_grist_ACLRules', None, {
        'resource': -2,
        # Include comments and unicode to check that renaming respects all that.
        'aclFormula': '( rec.schoolName !=  # ünîcødé comment\n  user.School.name)',
        'permissionsText': 'none',
      }],
      ['AddRecord', '_grist_ACLRules', None, {
        'resource': -3,
        'permissionsText': 'all'
      }],
    )])

    # Here's what we expect to be in the ACL tables (for reference in tests below).
    self.assertTableData('_grist_ACLResources', cols="subset", data=[
      ['id',  'tableId',  'colIds'],
      [1,     '*',        '*'],
      [2,     'Students', 'firstName,lastName'],
      [3,     'Students', '*'],
    ])
    self.assertTableData('_grist_ACLRules', cols="subset", data=[
      ['id',  'resource', 'aclFormula', 'permissionsText', 'userAttributes'],
      [1,     1,          '',           '',                json.dumps(user_attr1)],
      [2,     2,  '( rec.schoolName !=  # ünîcødé comment\n  user.School.name)', 'none', ''],
      [3,     3,          '',           'all',              ''],
    ])

